@namespace Components

<fieldset>
    <h3>Payment Information</h3>

    <label>
        Card Number
        <input @bind="Payment.CardNumber" @bind:event="oninput" />
    </label>

    <label>
        Expiry Date
        <input @bind="Payment.ExpiryDate" @bind:event="oninput" placeholder="MM/YY" />
    </label>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="validation-error" role="alert">@_errorMessage</div>
    }

    <div class="button-group">
        <button type="button" @onclick="HandleBack">Back</button>
        <button type="button" @onclick="HandlePlaceOrder">Place Order</button>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired]
    public PaymentInfo Payment { get; set; } = default!;

    [Parameter]
    public EventCallback OnBack { get; set; }

    [Parameter]
    public EventCallback OnPlaceOrder { get; set; }

    private string? _errorMessage;

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandlePlaceOrder()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(Payment.CardNumber)
            || string.IsNullOrWhiteSpace(Payment.ExpiryDate))
        {
            _errorMessage = "All fields are required.";
            return;
        }

        await OnPlaceOrder.InvokeAsync();
    }
}
